using Acme.Outbox;
using Acme.Workers;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<IOutboxStore, SqlOutboxStore>();
builder.Services.AddSingleton<IMessageBus, RabbitMessageBus>();
builder.Services.AddHostedService<OutboxRelay>();

var app = builder.Build();

app.MapGet("/healthz", () => Results.Ok());

app.Run();

using Acme.Outbox;

namespace Acme.Workers;

public sealed class OutboxRelay(IOutboxStore outbox, IMessageBus bus, ILogger<OutboxRelay> logger)
    : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (true)
        {
            foreach (var message in outbox.Pending(100))
            {
                await bus.PublishAsync(message);
                outbox.MarkSent(message.Id);
            }
            Thread.Sleep(5000);
        }
    }
}

